INSERT INTO public.cards(id,type,category_id,title,formula,description,how_to_apply,why_learn,batch_id) VALUES ('skill_boundaries','skill','master_client','Профессиональные границы','Факт + Граница + Альтернатива','Спокойно назовите факт, обозначьте, что вы делаете и чего не делаете, и сразу предложите приемлемый вариант.','["Факт: «Мы обсуждали это до процедуры».", "Граница: «Бесплатно переделать я не могу».", "Альтернатива: «Могу предложить коррекцию со скидкой»."]'::jsonb,'Границы без агрессии защищают и мастера, и репутацию салона.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,formula,description,how_to_apply,why_learn,batch_id) VALUES ('skill_expert_argument','skill','master_client','Экспертное обоснование','Причина + Последствие + Рекомендация','Объясните решение языком профессионала: почему так, что будет иначе и как лучше поступить.','["Причина: состояние волос/ногтей, технология.", "Последствие: риск для здоровья или качества.", "Рекомендация: конкретный следующий шаг."]'::jsonb,'Клиент доверяет мастеру, который понятно объясняет, а не оправдывается.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,formula,description,how_to_apply,why_learn,batch_id) VALUES ('skill_deescalation','skill','master_client','Снижение накала','Пауза + Признание чувств + Переход к делу','Не отвечайте на эмоцию эмоцией. Признайте чувства клиента и переведите разговор в спокойное русло.','["Сделайте паузу, говорите тише и медленнее.", "«Я вижу, что вы расстроены».", "«Давайте спокойно разберёмся, что можно сделать»."]'::jsonb,'Спокойствие мастера гасит скандал быстрее любых аргументов.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,formula,description,how_to_apply,why_learn,batch_id) VALUES ('skill_call_admin','skill','master_client','Привлечение администратора','Остановка + Приглашение + Передача','Когда разговор переходит в оскорбления или угрозы — остановите процедуру и подключите администратора.','["«Я остановлю процедуру, чтобы мы спокойно всё обсудили».", "Пригласите администратора, кратко изложите факты.", "Не продолжайте спор при клиенте."]'::jsonb,'Мастер не обязан выдерживать оскорбления в одиночку: салон — это команда.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,formula,description,how_to_apply,why_learn,batch_id) VALUES ('skill_rules_policy','skill','master_client','Опора на правила салона','Правило + Зачем оно + Что можно','Ссылайтесь не на своё мнение, а на правила салона и объясните, кого они защищают.','["«В нашем салоне действует правило…».", "«Оно нужно, чтобы…» (безопасность, комфорт, качество).", "«Вы можете…» — предложите разрешённый вариант."]'::jsonb,'Правило снимает личный конфликт: спорят не с мастером, а с политикой.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,formula,description,how_to_apply,why_learn,batch_id) VALUES ('skill_concrete_brief','skill','master_client','Перевод в конкретику','Уточнение + Фиксация + Согласие','Превратите размытые ожидания в чёткое задание: уточните детали, зафиксируйте их и получите согласие.','["Задайте 2–3 уточняющих вопроса.", "Покажите фото/палитру, проговорите результат.", "«Правильно ли я понимаю, что…?» — получите «да»."]'::jsonb,'Чёткое ТЗ до процедуры — лучшая защита от претензий после.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,formula,description,how_to_apply,why_learn,batch_id) VALUES ('skill_choice','skill','master_client','Выбор без давления','Вариант А + Вариант Б + Решение за клиентом','Предложите два понятных варианта и оставьте выбор клиенту — так он не чувствует, что его загнали в угол.','["Опишите оба варианта честно, с ценой и сроками.", "Не навязывайте, но порекомендуйте.", "«Как вам удобнее?»"]'::jsonb,'Выбор возвращает клиенту ощущение контроля и снимает протест.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,formula,description,how_to_apply,why_learn,batch_id) VALUES ('skill_dignity','skill','master_client','Сохранение достоинства','Спокойный тон + Без оправданий + Без нападения','Не оправдывайтесь и не нападайте в ответ. Говорите от себя, коротко и уверенно.','["Используйте «я-сообщения».", "Не отвечайте на оскорбления по существу.", "Короткие фразы, ровный голос."]'::jsonb,'Уверенный мастер вызывает уважение даже у конфликтного клиента.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,title,description,batch_id) VALUES ('role_master','role','master_client','Мастер','Вы — мастер салона красоты.','beauty_v1'),('role_client','role','master_client','Клиентка','Вы — клиентка салона.','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_01','solution','master_client','master_client','scn_01_1','Переделка по чужому образцу','Дать профессионально обоснованный ответ, защитить свои границы, не поддаться на манипуляции и сохранить репутацию салона. При конфликте — вежливо отказать и при необходимости привлечь администратора.','«Я понимаю, что вы ждали результат как на фото. Перед процедурой мы обсуждали, что из-за состояния волос точного попадания не будет. Повторное окрашивание сегодня повредит волосы. Предлагаю уход и тонирование через 2 недели со скидкой». При угрозах — спокойно пригласить администратора.','[]'::jsonb,'[]'::jsonb,'1','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('1.1','situation','master_client','master_client','scn_01_1','Переделка по чужому образцу · Вопрос','Клиентка требует переделать окрашивание, потому что цвет не совпадает с фото, хотя мастер предупреждал о невозможности точного попадания из-за состояния волос.','Можно ли что-то добавить, чтобы цвет был ближе к фото?','[{"who": "Клиентка", "line": "Можно ли что-то добавить, чтобы цвет был ближе к фото?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'1.1','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_01_1','master_client','master_client','Переделка по чужому образцу',1,'1.1','["skill_expert_argument", "skill_boundaries"]'::jsonb,'sol_01','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('1.2','situation','master_client','master_client','scn_01_2','Переделка по чужому образцу · Просьба','Клиентка требует переделать окрашивание, потому что цвет не совпадает с фото, хотя мастер предупреждал о невозможности точного попадания из-за состояния волос.','Я прошу вас сделать ещё одну процедуру сейчас, чтобы довести до идеала.','[{"who": "Клиентка", "line": "Я прошу вас сделать ещё одну процедуру сейчас, чтобы довести до идеала."}, {"who": "Вы", "line": "…"}]'::jsonb,2,'1.2','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_01_2','master_client','master_client','Переделка по чужому образцу',2,'1.2','["skill_expert_argument", "skill_boundaries"]'::jsonb,'sol_01','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('1.3','situation','master_client','master_client','scn_01_3','Переделка по чужому образцу · Требование','Клиентка требует переделать окрашивание, потому что цвет не совпадает с фото, хотя мастер предупреждал о невозможности точного попадания из-за состояния волос.','Вы обязаны переделать бесплатно, иначе я устрою скандал и ничего не заплачу!','[{"who": "Клиентка", "line": "Вы обязаны переделать бесплатно, иначе я устрою скандал и ничего не заплачу!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'1.3','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_01_3','master_client','master_client','Переделка по чужому образцу',3,'1.3','["skill_expert_argument", "skill_boundaries"]'::jsonb,'sol_01','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_02','solution','master_client','master_client','scn_02_1','Отказ оплачивать услугу после предупреждения','Отстоять свою профессиональную позицию, получить оплату за работу, не потерять лицо и не раздуть конфликт.','«Мне важно, чтобы вы ушли довольной. Давайте разберём, что именно не устраивает. Работа выполнена по согласованной технологии, о нюансах мы говорили заранее, поэтому она оплачивается полностью. Могу бесплатно подправить форму/укладку прямо сейчас». При отказе платить — администратор.','[]'::jsonb,'[]'::jsonb,'2','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('2.1','situation','master_client','master_client','scn_02_1','Отказ оплачивать услугу после предупреждения · Вопрос','Клиент требует скидку или отказывается платить, потому что результат не совпал с его ожиданиями, хотя мастер предупреждал о возможных нюансах.','Можно сделать скидку? Результат немного не такой.','[{"who": "Клиентка", "line": "Можно сделать скидку? Результат немного не такой."}, {"who": "Вы", "line": "…"}]'::jsonb,1,'2.1','skill_boundaries','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_02_1','master_client','master_client','Отказ оплачивать услугу после предупреждения',1,'2.1','["skill_boundaries", "skill_deescalation"]'::jsonb,'sol_02','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('2.2','situation','master_client','master_client','scn_02_2','Отказ оплачивать услугу после предупреждения · Просьба','Клиент требует скидку или отказывается платить, потому что результат не совпал с его ожиданиями, хотя мастер предупреждал о возможных нюансах.','Я настаиваю на скидке, потому что я недовольна.','[{"who": "Клиентка", "line": "Я настаиваю на скидке, потому что я недовольна."}, {"who": "Вы", "line": "…"}]'::jsonb,2,'2.2','skill_boundaries','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_02_2','master_client','master_client','Отказ оплачивать услугу после предупреждения',2,'2.2','["skill_boundaries", "skill_deescalation"]'::jsonb,'sol_02','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('2.3','situation','master_client','master_client','scn_02_3','Отказ оплачивать услугу после предупреждения · Требование','Клиент требует скидку или отказывается платить, потому что результат не совпал с его ожиданиями, хотя мастер предупреждал о возможных нюансах.','Я не буду платить, это халтура!','[{"who": "Клиентка", "line": "Я не буду платить, это халтура!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'2.3','skill_boundaries','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_02_3','master_client','master_client','Отказ оплачивать услугу после предупреждения',3,'2.3','["skill_boundaries", "skill_deescalation"]'::jsonb,'sol_02','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_03','solution','master_client','master_client','scn_03_1','Манипуляция с предоплатой и угроза отзывом','Объяснить правило предоплаты как защиту от неявок, предложить альтернативу (например, залог наличными при входе), не поддаваться на шантаж.','«Предоплата — общее правило при нескольких отменах, оно защищает время мастера и других клиентов. Вы можете внести предоплату переводом или оставить залог наличными при визите — как вам удобнее?» На угрозу отзывом не реагировать, правило не менять.','[]'::jsonb,'[]'::jsonb,'3','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('3.1','situation','master_client','master_client','scn_03_1','Манипуляция с предоплатой и угроза отзывом · Вопрос','Клиентка, которая уже несколько раз отменяла запись в последний момент, требует записать без предоплаты, угрожая негативными отзывами.','Почему я должна платить предоплату? Это новое правило?','[{"who": "Клиентка", "line": "Почему я должна платить предоплату? Это новое правило?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'3.1','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_03_1','master_client','master_client','Манипуляция с предоплатой и угроза отзывом',1,'3.1','["skill_rules_policy", "skill_choice"]'::jsonb,'sol_03','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('3.2','situation','master_client','master_client','scn_03_2','Манипуляция с предоплатой и угроза отзывом · Просьба','Клиентка, которая уже несколько раз отменяла запись в последний момент, требует записать без предоплаты, угрожая негативными отзывами.','Я не могу сейчас перевести, запишите меня, я обещаю прийти. Сделайте исключение.','[{"who": "Клиентка", "line": "Я не могу сейчас перевести, запишите меня, я обещаю прийти. Сделайте исключение."}, {"who": "Вы", "line": "…"}]'::jsonb,2,'3.2','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_03_2','master_client','master_client','Манипуляция с предоплатой и угроза отзывом',2,'3.2','["skill_rules_policy", "skill_choice"]'::jsonb,'sol_03','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('3.3','situation','master_client','master_client','scn_03_3','Манипуляция с предоплатой и угроза отзывом · Требование','Клиентка, которая уже несколько раз отменяла запись в последний момент, требует записать без предоплаты, угрожая негативными отзывами.','Это дискриминация! Если не запишете — напишу негативный отзыв и всем расскажу, как вы обращаетесь с клиентами!','[{"who": "Клиентка", "line": "Это дискриминация! Если не запишете — напишу негативный отзыв и всем расскажу, как вы обращаетесь с клиентами!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'3.3','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_03_3','master_client','master_client','Манипуляция с предоплатой и угроза отзывом',3,'3.3','["skill_rules_policy", "skill_choice"]'::jsonb,'sol_03','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_04','solution','master_client','master_client','scn_04_1','Обесценивание бесплатной услуги','Не вступать в переписку, не признавать вину, при оскорблениях — завершить общение, впредь осторожнее выбирать клиентов для бесплатных услуг.','Один короткий корректный ответ: «Спасибо за обратную связь. Процедура выполнена по согласованной технологии. Небольшую коррекцию могу сделать в удобное время». На оскорбления — не отвечать, завершить переписку, при необходимости заблокировать.','[]'::jsonb,'[]'::jsonb,'4','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('4.1','situation','master_client','master_client','scn_04_1','Обесценивание бесплатной услуги · Вопрос','Клиентка согласилась на бесплатную процедуру для портфолио, но после осталась недовольна и начала оскорблять мастера в переписке, требуя компенсации.','Можно немного подправить? Я не совсем довольна.','[{"who": "Клиентка", "line": "Можно немного подправить? Я не совсем довольна."}, {"who": "Вы", "line": "…"}]'::jsonb,1,'4.1','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_04_1','master_client','master_client','Обесценивание бесплатной услуги',1,'4.1','["skill_dignity", "skill_boundaries"]'::jsonb,'sol_04','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('4.2','situation','master_client','master_client','scn_04_2','Обесценивание бесплатной услуги · Просьба','Клиентка согласилась на бесплатную процедуру для портфолио, но после осталась недовольна и начала оскорблять мастера в переписке, требуя компенсации.','Я потратила время, вы могли бы переделать или дать компенсацию.','[{"who": "Клиентка", "line": "Я потратила время, вы могли бы переделать или дать компенсацию."}, {"who": "Вы", "line": "…"}]'::jsonb,2,'4.2','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_04_2','master_client','master_client','Обесценивание бесплатной услуги',2,'4.2','["skill_dignity", "skill_boundaries"]'::jsonb,'sol_04','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('4.3','situation','master_client','master_client','scn_04_3','Обесценивание бесплатной услуги · Требование','Клиентка согласилась на бесплатную процедуру для портфолио, но после осталась недовольна и начала оскорблять мастера в переписке, требуя компенсации.','Ты не умеешь работать! Ты мне всё испортила! Требую компенсацию за моральный ущерб!','[{"who": "Клиентка", "line": "Ты не умеешь работать! Ты мне всё испортила! Требую компенсацию за моральный ущерб!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'4.3','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_04_3','master_client','master_client','Обесценивание бесплатной услуги',3,'4.3','["skill_dignity", "skill_boundaries"]'::jsonb,'sol_04','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_05','solution','master_client','master_client','scn_05_1','Вторжение в личное пространство и оскорбления','Вежливо пресечь личные вопросы, перевести в рабочее русло. При оскорблениях — остановить процедуру и привлечь администратора.','«Давайте я лучше расскажу, что сейчас делаю с вашими волосами», — мягко вернуть к процедуре. «О личном я на работе не говорю». При оскорблениях: «Я остановлю процедуру и приглашу администратора».','[]'::jsonb,'[]'::jsonb,'5','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('5.1','situation','master_client','master_client','scn_05_1','Вторжение в личное пространство и оскорбления · Вопрос','Клиентка во время процедуры задаёт провокационные вопросы о внешности, возрасте, личной жизни мастера, допускает оскорбления.','Сколько вам лет? Вы давно работаете?','[{"who": "Клиентка", "line": "Сколько вам лет? Вы давно работаете?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'5.1','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_05_1','master_client','master_client','Вторжение в личное пространство и оскорбления',1,'5.1','["skill_dignity", "skill_call_admin"]'::jsonb,'sol_05','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('5.2','situation','master_client','master_client','scn_05_2','Вторжение в личное пространство и оскорбления · Просьба','Клиентка во время процедуры задаёт провокационные вопросы о внешности, возрасте, личной жизни мастера, допускает оскорбления.','Почему у вас такой цвет волос? А вы не против, если я спрошу про вашу личную жизнь?','[{"who": "Клиентка", "line": "Почему у вас такой цвет волос? А вы не против, если я спрошу про вашу личную жизнь?"}, {"who": "Вы", "line": "…"}]'::jsonb,2,'5.2','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_05_2','master_client','master_client','Вторжение в личное пространство и оскорбления',2,'5.2','["skill_dignity", "skill_call_admin"]'::jsonb,'sol_05','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('5.3','situation','master_client','master_client','scn_05_3','Вторжение в личное пространство и оскорбления · Требование','Клиентка во время процедуры задаёт провокационные вопросы о внешности, возрасте, личной жизни мастера, допускает оскорбления.','У вас самой руки не ухожены! Вы вообще не профессионал! Где вы учились?','[{"who": "Клиентка", "line": "У вас самой руки не ухожены! Вы вообще не профессионал! Где вы учились?"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'5.3','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_05_3','master_client','master_client','Вторжение в личное пространство и оскорбления',3,'5.3','["skill_dignity", "skill_call_admin"]'::jsonb,'sol_05','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_06','solution','master_client','master_client','scn_06_1','Вмешательство в процесс и обучение мастера','Спокойно обосновать свою технологию, не поддаваться на давление, предотвратить риск травмы. Если клиентка не успокаивается — прекратить процедуру с сохранением достоинства.','«Я работаю по этой технологии, потому что она безопасна для вашей кожи/ногтей. Если вам важна какая-то деталь — скажите, учту её в результате. Пожалуйста, держите руку неподвижно — так я не травмирую вас». При продолжении давления — остановить процедуру.','[]'::jsonb,'[]'::jsonb,'6','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('6.1','situation','master_client','master_client','scn_06_1','Вмешательство в процесс и обучение мастера · Вопрос','Клиентка постоянно комментирует и критикует каждый шаг мастера, утверждая, что «у предыдущего мастера было лучше», и требует делать так, как она говорит.','А почему вы делаете именно так?','[{"who": "Клиентка", "line": "А почему вы делаете именно так?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'6.1','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_06_1','master_client','master_client','Вмешательство в процесс и обучение мастера',1,'6.1','["skill_expert_argument", "skill_dignity"]'::jsonb,'sol_06','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('6.2','situation','master_client','master_client','scn_06_2','Вмешательство в процесс и обучение мастера · Просьба','Клиентка постоянно комментирует и критикует каждый шаг мастера, утверждая, что «у предыдущего мастера было лучше», и требует делать так, как она говорит.','Вы не могли бы сделать, как мой предыдущий мастер?','[{"who": "Клиентка", "line": "Вы не могли бы сделать, как мой предыдущий мастер?"}, {"who": "Вы", "line": "…"}]'::jsonb,2,'6.2','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_06_2','master_client','master_client','Вмешательство в процесс и обучение мастера',2,'6.2','["skill_expert_argument", "skill_dignity"]'::jsonb,'sol_06','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('6.3','situation','master_client','master_client','scn_06_3','Вмешательство в процесс и обучение мастера · Требование','Клиентка постоянно комментирует и критикует каждый шаг мастера, утверждая, что «у предыдущего мастера было лучше», и требует делать так, как она говорит.','Вы делаете всё не так! Делайте, как я говорю!','[{"who": "Клиентка", "line": "Вы делаете всё не так! Делайте, как я говорю!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'6.3','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_06_3','master_client','master_client','Вмешательство в процесс и обучение мастера',3,'6.3','["skill_expert_argument", "skill_dignity"]'::jsonb,'sol_06','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_07','solution','master_client','master_client','scn_07_1','Требование сложной услуги за короткое время','Отстоять технические требования к процедуре, не брать на себя риск низкого качества, не допустить конфликта, предложив альтернативу.','«За 20 минут полноценную процедуру качественно не сделать — пострадает результат. Могу предложить экспресс-вариант за это время или записать вас на полную процедуру на ближайшее свободное время. Что выберете?»','[]'::jsonb,'[]'::jsonb,'7','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('7.1','situation','master_client','master_client','scn_07_1','Требование сложной услуги за короткое время · Вопрос','Клиентка требует полноценную процедуру за время, вдвое меньше необходимого, отказываясь понимать профессиональные ограничения.','Можно сделать простую укладку за 20 минут?','[{"who": "Клиентка", "line": "Можно сделать простую укладку за 20 минут?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'7.1','skill_choice','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_07_1','master_client','master_client','Требование сложной услуги за короткое время',1,'7.1','["skill_choice", "skill_expert_argument"]'::jsonb,'sol_07','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('7.2','situation','master_client','master_client','scn_07_2','Требование сложной услуги за короткое время · Просьба','Клиентка требует полноценную процедуру за время, вдвое меньше необходимого, отказываясь понимать профессиональные ограничения.','Я прошу вас сделать полноценную процедуру быстрее, я доплачу!','[{"who": "Клиентка", "line": "Я прошу вас сделать полноценную процедуру быстрее, я доплачу!"}, {"who": "Вы", "line": "…"}]'::jsonb,2,'7.2','skill_choice','beauty_v1') ON CONFLICT (id) DO NOTHING;
