INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('7.3','situation','master_client','master_client','scn_07_3','Требование сложной услуги за короткое время · Требование','Клиентка требует полноценную процедуру за время, вдвое меньше необходимого, отказываясь понимать профессиональные ограничения.','Вы обязаны обслужить меня сейчас, иначе я устрою скандал!','[{"who": "Клиентка", "line": "Вы обязаны обслужить меня сейчас, иначе я устрою скандал!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'7.3','skill_choice','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_07_3','master_client','master_client','Требование сложной услуги за короткое время',3,'7.3','["skill_choice", "skill_expert_argument"]'::jsonb,'sol_07','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_08','solution','master_client','master_client','scn_08_1','Сломанный маникюр после нарушения рекомендаций','Отстоять профессиональную репутацию, вежливо напомнить о рекомендациях, предложить платный ремонт, не поддаваться на шантаж.','«Мне жаль, что так вышло. Давайте посмотрим ноготь. Такой скол обычно возникает при механической нагрузке — помните, мы говорили про перчатки? Ремонт одного ногтя займёт 15 минут, стоимость — по прайсу. Могу сделать прямо сейчас».','[]'::jsonb,'[]'::jsonb,'8','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('8.1','situation','master_client','master_client','scn_08_1','Сломанный маникюр после нарушения рекомендаций · Вопрос','Клиентка нарушила рекомендации по уходу, в результате сломался ноготь, и теперь она требует бесплатного ремонта, обвиняя мастера в некачественной работе.','Что делать, если сломался ноготь через день?','[{"who": "Клиентка", "line": "Что делать, если сломался ноготь через день?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'8.1','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_08_1','master_client','master_client','Сломанный маникюр после нарушения рекомендаций',1,'8.1','["skill_expert_argument", "skill_boundaries"]'::jsonb,'sol_08','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('8.2','situation','master_client','master_client','scn_08_2','Сломанный маникюр после нарушения рекомендаций · Просьба','Клиентка нарушила рекомендации по уходу, в результате сломался ноготь, и теперь она требует бесплатного ремонта, обвиняя мастера в некачественной работе.','Отремонтируйте бесплатно, я же платила деньги!','[{"who": "Клиентка", "line": "Отремонтируйте бесплатно, я же платила деньги!"}, {"who": "Вы", "line": "…"}]'::jsonb,2,'8.2','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_08_2','master_client','master_client','Сломанный маникюр после нарушения рекомендаций',2,'8.2','["skill_expert_argument", "skill_boundaries"]'::jsonb,'sol_08','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('8.3','situation','master_client','master_client','scn_08_3','Сломанный маникюр после нарушения рекомендаций · Требование','Клиентка нарушила рекомендации по уходу, в результате сломался ноготь, и теперь она требует бесплатного ремонта, обвиняя мастера в некачественной работе.','Это брак! Верните деньги или я всё расскажу!','[{"who": "Клиентка", "line": "Это брак! Верните деньги или я всё расскажу!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'8.3','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_08_3','master_client','master_client','Сломанный маникюр после нарушения рекомендаций',3,'8.3','["skill_expert_argument", "skill_boundaries"]'::jsonb,'sol_08','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_09','solution','master_client','master_client','scn_09_1','Публичный скандал и унижение','Не вступать в публичную перепалку, сохранять достоинство, предложить перенести обсуждение, привлечь администратора.','Тихо и спокойно: «Я готова всё обсудить. Давайте пройдём в отдельную зону, там нам будет удобнее». Пригласить администратора. В перепалку не вступать, оправданий при всех не произносить.','[]'::jsonb,'[]'::jsonb,'9','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('9.1','situation','master_client','master_client','scn_09_1','Публичный скандал и унижение · Вопрос','Клиентка недовольна и устраивает скандал на весь зал, оскорбляя мастера и привлекая внимание других клиентов.','Я хочу обсудить результат при всех, потому что я недовольна.','[{"who": "Клиентка", "line": "Я хочу обсудить результат при всех, потому что я недовольна."}, {"who": "Вы", "line": "…"}]'::jsonb,1,'9.1','skill_deescalation','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_09_1','master_client','master_client','Публичный скандал и унижение',1,'9.1','["skill_deescalation", "skill_call_admin"]'::jsonb,'sol_09','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('9.2','situation','master_client','master_client','scn_09_2','Публичный скандал и унижение · Просьба','Клиентка недовольна и устраивает скандал на весь зал, оскорбляя мастера и привлекая внимание других клиентов.','Все сюда посмотрите, что мне сделали!','[{"who": "Клиентка", "line": "Все сюда посмотрите, что мне сделали!"}, {"who": "Вы", "line": "…"}]'::jsonb,2,'9.2','skill_deescalation','beauty_v1') ON CONFLICT (id) DO NOTHING;
