INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('9.3','situation','master_client','master_client','scn_09_3','Публичный скандал и унижение · Требование','Клиентка недовольна и устраивает скандал на весь зал, оскорбляя мастера и привлекая внимание других клиентов.','Вы никчёмный мастер, я уничтожу вашу репутацию!','[{"who": "Клиентка", "line": "Вы никчёмный мастер, я уничтожу вашу репутацию!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'9.3','skill_deescalation','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_09_3','master_client','master_client','Публичный скандал и унижение',3,'9.3','["skill_deescalation", "skill_call_admin"]'::jsonb,'sol_09','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_10','solution','master_client','master_client','scn_10_1','Размытое ТЗ и поиск виноватого','Перевести клиентку в зону конкретики, защититься от «размытой критики», предложить фиксацию результата (фото) и согласование деталей перед процедурой.','До процедуры: «Давайте уточним: длина, форма, оттенок — как на этом фото?» После претензии: «Что конкретно отличается? Покажите, я поправлю». Впредь фиксировать результат на фото и согласовывать детали.','[]'::jsonb,'[]'::jsonb,'10','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('10.1','situation','master_client','master_client','scn_10_1','Размытое ТЗ и поиск виноватого · Вопрос','Клиентка даёт размытое задание «сделайте как обычно, но лучше», а после процедуры критикует результат, обвиняя мастера в непонимании.','Сделайте так же, как в прошлый раз, только постарайтесь.','[{"who": "Клиентка", "line": "Сделайте так же, как в прошлый раз, только постарайтесь."}, {"who": "Вы", "line": "…"}]'::jsonb,1,'10.1','skill_concrete_brief','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_10_1','master_client','master_client','Размытое ТЗ и поиск виноватого',1,'10.1','["skill_concrete_brief", "skill_deescalation"]'::jsonb,'sol_10','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('10.2','situation','master_client','master_client','scn_10_2','Размытое ТЗ и поиск виноватого · Просьба','Клиентка даёт размытое задание «сделайте как обычно, но лучше», а после процедуры критикует результат, обвиняя мастера в непонимании.','Вы знаете, что мне нравится, просто сделайте идеально.','[{"who": "Клиентка", "line": "Вы знаете, что мне нравится, просто сделайте идеально."}, {"who": "Вы", "line": "…"}]'::jsonb,2,'10.2','skill_concrete_brief','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_10_2','master_client','master_client','Размытое ТЗ и поиск виноватого',2,'10.2','["skill_concrete_brief", "skill_deescalation"]'::jsonb,'sol_10','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('10.3','situation','master_client','master_client','scn_10_3','Размытое ТЗ и поиск виноватого · Требование','Клиентка даёт размытое задание «сделайте как обычно, но лучше», а после процедуры критикует результат, обвиняя мастера в непонимании.','Вы сделали хуже, чем в прошлый раз! Переделывайте!','[{"who": "Клиентка", "line": "Вы сделали хуже, чем в прошлый раз! Переделывайте!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'10.3','skill_concrete_brief','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_10_3','master_client','master_client','Размытое ТЗ и поиск виноватого',3,'10.3','["skill_concrete_brief", "skill_deescalation"]'::jsonb,'sol_10','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_11','solution','master_client','master_client','scn_11_1','Клиентка требует другого мастера во время процедуры','Сохранять профессиональное спокойствие. Предложить закончить процедуру сейчас, а в следующий раз записаться к другому специалисту.','«Я вас понимаю. У коллеги сейчас другой клиент. Я аккуратно закончу процедуру, а на следующий визит администратор запишет вас к ней». При требовании — пригласить администратора, не принимая на свой счёт.','[]'::jsonb,'[]'::jsonb,'11','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('11.1','situation','master_client','master_client','scn_11_1','Клиентка требует другого мастера во время процедуры · Вопрос','Мастер уже начал работу (сняла старое покрытие или нанесла базу). Внезапно клиентка заявляет, что хочет, чтобы процедуру заканчивал другой мастер.','А можно, чтобы процедуру закончила вон та девушка?','[{"who": "Клиентка", "line": "А можно, чтобы процедуру закончила вон та девушка?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'11.1','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_11_1','master_client','master_client','Клиентка требует другого мастера во время процедуры',1,'11.1','["skill_dignity", "skill_choice"]'::jsonb,'sol_11','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('11.2','situation','master_client','master_client','scn_11_2','Клиентка требует другого мастера во время процедуры · Просьба','Мастер уже начал работу (сняла старое покрытие или нанесла базу). Внезапно клиентка заявляет, что хочет, чтобы процедуру заканчивал другой мастер.','Я понимаю, что вы уже начали, но я буду спокойнее, если работу закончит другой мастер.','[{"who": "Клиентка", "line": "Я понимаю, что вы уже начали, но я буду спокойнее, если работу закончит другой мастер."}, {"who": "Вы", "line": "…"}]'::jsonb,2,'11.2','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_11_2','master_client','master_client','Клиентка требует другого мастера во время процедуры',2,'11.2','["skill_dignity", "skill_choice"]'::jsonb,'sol_11','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('11.3','situation','master_client','master_client','scn_11_3','Клиентка требует другого мастера во время процедуры · Требование','Мастер уже начал работу (сняла старое покрытие или нанесла базу). Внезапно клиентка заявляет, что хочет, чтобы процедуру заканчивал другой мастер.','Я не хочу, чтобы вы меня трогали! Позовите другого мастера, иначе я уйду и ничего не заплачу!','[{"who": "Клиентка", "line": "Я не хочу, чтобы вы меня трогали! Позовите другого мастера, иначе я уйду и ничего не заплачу!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'11.3','skill_dignity','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_11_3','master_client','master_client','Клиентка требует другого мастера во время процедуры',3,'11.3','["skill_dignity", "skill_choice"]'::jsonb,'sol_11','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_12','solution','master_client','master_client','scn_12_1','Клиентка снимает процесс на видео без разрешения','Чётко и вежливо объяснить политику салона: съёмка без согласия мастера и администрации запрещена. Предложить альтернативу.','«В салоне съёмка процесса возможна только с согласия мастера — здесь другие клиенты и рабочие материалы. Давайте я сделаю красивое фото готового результата для ваших соцсетей?»','[]'::jsonb,'[]'::jsonb,'12','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('12.1','situation','master_client','master_client','scn_12_1','Клиентка снимает процесс на видео без разрешения · Вопрос','Во время процедуры клиентка начинает снимать процесс на видео, не спросив разрешения мастера, и продолжает после просьбы прекратить.','Я могу снять процесс для своих соцсетей? Вы не против?','[{"who": "Клиентка", "line": "Я могу снять процесс для своих соцсетей? Вы не против?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'12.1','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_12_1','master_client','master_client','Клиентка снимает процесс на видео без разрешения',1,'12.1','["skill_rules_policy", "skill_choice"]'::jsonb,'sol_12','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('12.2','situation','master_client','master_client','scn_12_2','Клиентка снимает процесс на видео без разрешения · Просьба','Во время процедуры клиентка начинает снимать процесс на видео, не спросив разрешения мастера, и продолжает после просьбы прекратить.','Я просто хочу показать подругам, как делают маникюр. Вы же не против?','[{"who": "Клиентка", "line": "Я просто хочу показать подругам, как делают маникюр. Вы же не против?"}, {"who": "Вы", "line": "…"}]'::jsonb,2,'12.2','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_12_2','master_client','master_client','Клиентка снимает процесс на видео без разрешения',2,'12.2','["skill_rules_policy", "skill_choice"]'::jsonb,'sol_12','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('12.3','situation','master_client','master_client','scn_12_3','Клиентка снимает процесс на видео без разрешения · Требование','Во время процедуры клиентка начинает снимать процесс на видео, не спросив разрешения мастера, и продолжает после просьбы прекратить.','Я имею право снимать то, за что плачу! Не мешайте мне!','[{"who": "Клиентка", "line": "Я имею право снимать то, за что плачу! Не мешайте мне!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'12.3','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_12_3','master_client','master_client','Клиентка снимает процесс на видео без разрешения',3,'12.3','["skill_rules_policy", "skill_choice"]'::jsonb,'sol_12','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_13','solution','master_client','master_client','scn_13_1','Клиентка приводит компанию и шумит','Мягко, но твёрдо обозначить правила салона. Если клиентка отказывается — привлечь администратора.','«Подруга может подождать в зоне ожидания — там есть чай. В рабочей зоне мы сохраняем тишину для всех гостей». При агрессии — пригласить администратора.','[]'::jsonb,'[]'::jsonb,'13','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('13.1','situation','master_client','master_client','scn_13_1','Клиентка приводит компанию и шумит · Вопрос','Клиентка пришла с подругами. Они громко разговаривают, включают музыку, мешают мастеру и другим клиентам. На замечания реагируют агрессивно.','А что, нельзя с подругой? Мы не шумим.','[{"who": "Клиентка", "line": "А что, нельзя с подругой? Мы не шумим."}, {"who": "Вы", "line": "…"}]'::jsonb,1,'13.1','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_13_1','master_client','master_client','Клиентка приводит компанию и шумит',1,'13.1','["skill_rules_policy", "skill_call_admin"]'::jsonb,'sol_13','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('13.2','situation','master_client','master_client','scn_13_2','Клиентка приводит компанию и шумит · Просьба','Клиентка пришла с подругами. Они громко разговаривают, включают музыку, мешают мастеру и другим клиентам. На замечания реагируют агрессивно.','Мы постараемся тише, но она просто посидит рядом, ладно?','[{"who": "Клиентка", "line": "Мы постараемся тише, но она просто посидит рядом, ладно?"}, {"who": "Вы", "line": "…"}]'::jsonb,2,'13.2','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
