INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('13.3','situation','master_client','master_client','scn_13_3','Клиентка приводит компанию и шумит · Требование','Клиентка пришла с подругами. Они громко разговаривают, включают музыку, мешают мастеру и другим клиентам. На замечания реагируют агрессивно.','Я плачу деньги и имею право приводить кого хочу! Не лезьте не в своё дело!','[{"who": "Клиентка", "line": "Я плачу деньги и имею право приводить кого хочу! Не лезьте не в своё дело!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'13.3','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
