INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_14','solution','master_client','master_client','scn_14_1','Возврат денег за услугу через месяц','Объяснить, что срок службы цвета зависит от ухода, напомнить о рекомендациях. Предложить платную коррекцию со скидкой как постоянной клиентке.','«Стойкость цвета во многом зависит от ухода — горячая вода и обычные шампуни быстро вымывают пигмент, мы об этом говорили. Вернуть деньги за выполненную услугу мы не можем, но я предложу вам тонирование со скидкой 20% как постоянной клиентке».','[]'::jsonb,'[]'::jsonb,'14','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('14.1','situation','master_client','master_client','scn_14_1','Возврат денег за услугу через месяц · Вопрос','Клиентка сделала сложное окрашивание и была довольна. Через месяц требует вернуть деньги, потому что «цвет выцвел», хотя не соблюдала рекомендации по уходу.','Цвет уже не тот, что был. Это нормально?','[{"who": "Клиентка", "line": "Цвет уже не тот, что был. Это нормально?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'14.1','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_14_1','master_client','master_client','Возврат денег за услугу через месяц',1,'14.1','["skill_expert_argument", "skill_choice"]'::jsonb,'sol_14','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('14.2','situation','master_client','master_client','scn_14_2','Возврат денег за услугу через месяц · Просьба','Клиентка сделала сложное окрашивание и была довольна. Через месяц требует вернуть деньги, потому что «цвет выцвел», хотя не соблюдала рекомендации по уходу.','Я хочу, чтобы вы вернули деньги или сделали новое окрашивание бесплатно.','[{"who": "Клиентка", "line": "Я хочу, чтобы вы вернули деньги или сделали новое окрашивание бесплатно."}, {"who": "Вы", "line": "…"}]'::jsonb,2,'14.2','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_14_2','master_client','master_client','Возврат денег за услугу через месяц',2,'14.2','["skill_expert_argument", "skill_choice"]'::jsonb,'sol_14','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('14.3','situation','master_client','master_client','scn_14_3','Возврат денег за услугу через месяц · Требование','Клиентка сделала сложное окрашивание и была довольна. Через месяц требует вернуть деньги, потому что «цвет выцвел», хотя не соблюдала рекомендации по уходу.','Это ваша плохая работа! Цвет держался всего месяц! Верните деньги, или я напишу жалобу!','[{"who": "Клиентка", "line": "Это ваша плохая работа! Цвет держался всего месяц! Верните деньги, или я напишу жалобу!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'14.3','skill_expert_argument','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_14_3','master_client','master_client','Возврат денег за услугу через месяц',3,'14.3','["skill_expert_argument", "skill_choice"]'::jsonb,'sol_14','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_15','solution','master_client','master_client','scn_15_1','Обвинение мастера в краже','Сохранять спокойствие, не реагировать на оскорбления, не признавать вину без доказательств.','«Я понимаю, как неприятно потерять украшение. Давайте вместе осмотрим рабочее место». Пригласить администратора, который проверит записи камер. На обвинения: «Вы вправе обратиться в полицию, мы предоставим записи».','[]'::jsonb,'[]'::jsonb,'15','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('15.1','situation','master_client','master_client','scn_15_1','Обвинение мастера в краже · Вопрос','После процедуры клиентка заявляет, что пропало кольцо, обвиняет мастера в краже и угрожает полицией. По камерам она вошла без украшения.','Вы не видели моё кольцо? Я снимала его перед процедурой.','[{"who": "Клиентка", "line": "Вы не видели моё кольцо? Я снимала его перед процедурой."}, {"who": "Вы", "line": "…"}]'::jsonb,1,'15.1','skill_deescalation','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_15_1','master_client','master_client','Обвинение мастера в краже',1,'15.1','["skill_deescalation", "skill_call_admin"]'::jsonb,'sol_15','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('15.2','situation','master_client','master_client','scn_15_2','Обвинение мастера в краже · Просьба','После процедуры клиентка заявляет, что пропало кольцо, обвиняет мастера в краже и угрожает полицией. По камерам она вошла без украшения.','Пожалуйста, проверьте свои вещи, может, оно случайно закатилось.','[{"who": "Клиентка", "line": "Пожалуйста, проверьте свои вещи, может, оно случайно закатилось."}, {"who": "Вы", "line": "…"}]'::jsonb,2,'15.2','skill_deescalation','beauty_v1') ON CONFLICT (id) DO NOTHING;
