INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('15.3','situation','master_client','master_client','scn_15_3','Обвинение мастера в краже · Требование','После процедуры клиентка заявляет, что пропало кольцо, обвиняет мастера в краже и угрожает полицией. По камерам она вошла без украшения.','Это вы украли! Я вызову полицию! Обыщите её сейчас же!','[{"who": "Клиентка", "line": "Это вы украли! Я вызову полицию! Обыщите её сейчас же!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'15.3','skill_deescalation','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_15_3','master_client','master_client','Обвинение мастера в краже',3,'15.3','["skill_deescalation", "skill_call_admin"]'::jsonb,'sol_15','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_16','solution','master_client','master_client','scn_16_1','Сложная работа и требование скидки','Спокойно объяснить, что сложность влияет на стоимость. Предложить выбор: полная стоимость с учётом сложности или базовая процедура.','«Стоимость зависит от объёма работы — это есть в нашем прайсе. Есть два варианта: полная процедура с глубокой обработкой по цене N или базовая без неё по обычной цене. Как вам удобнее?»','[]'::jsonb,'[]'::jsonb,'16','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('16.1','situation','master_client','master_client','scn_16_1','Сложная работа и требование скидки · Вопрос','Клиентка пришла с сильно запущенными волосами или ногтями. Мастер предупреждает о доплате, а клиентка требует сделать «как обычно» и дать скидку.','Почему это стоит дороже? Я же просто на маникюр пришла.','[{"who": "Клиентка", "line": "Почему это стоит дороже? Я же просто на маникюр пришла."}, {"who": "Вы", "line": "…"}]'::jsonb,1,'16.1','skill_choice','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_16_1','master_client','master_client','Сложная работа и требование скидки',1,'16.1','["skill_choice", "skill_rules_policy"]'::jsonb,'sol_16','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('16.2','situation','master_client','master_client','scn_16_2','Сложная работа и требование скидки · Просьба','Клиентка пришла с сильно запущенными волосами или ногтями. Мастер предупреждает о доплате, а клиентка требует сделать «как обычно» и дать скидку.','Я не знала, что это так сложно. Может, сделаете скидку?','[{"who": "Клиентка", "line": "Я не знала, что это так сложно. Может, сделаете скидку?"}, {"who": "Вы", "line": "…"}]'::jsonb,2,'16.2','skill_choice','beauty_v1') ON CONFLICT (id) DO NOTHING;
