INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('16.3','situation','master_client','master_client','scn_16_3','Сложная работа и требование скидки · Требование','Клиентка пришла с сильно запущенными волосами или ногтями. Мастер предупреждает о доплате, а клиентка требует сделать «как обычно» и дать скидку.','Вы что, хотите содрать с меня лишние деньги? Я не буду платить больше!','[{"who": "Клиентка", "line": "Вы что, хотите содрать с меня лишние деньги? Я не буду платить больше!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'16.3','skill_choice','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.scenarios(id,category_id,direction_id,title,level,situation_id,skill_ids,solution_id,batch_id) VALUES ('scn_16_3','master_client','master_client','Сложная работа и требование скидки',3,'16.3','["skill_choice", "skill_rules_policy"]'::jsonb,'sol_16','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_17','solution','master_client','master_client','scn_17_1','Ребёнок мешает процедуре','Мягко, но твёрдо объяснить правила салона. Предложить альтернативу: перенос записи или присмотр в зоне ожидания.','«Здесь острые инструменты и препараты — это небезопасно для малыша. Он может побыть в зоне ожидания под присмотром администратора, или давайте перенесём запись на удобное время».','[]'::jsonb,'[]'::jsonb,'17','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('17.1','situation','master_client','master_client','scn_17_1','Ребёнок мешает процедуре · Вопрос','Клиентка пришла с ребёнком 3–6 лет. Ребёнок бегает, трогает инструменты, кричит. На просьбу успокоить его клиентка реагирует агрессивно.','Я не могла оставить его с няней, он будет себя хорошо вести. Вы не против?','[{"who": "Клиентка", "line": "Я не могла оставить его с няней, он будет себя хорошо вести. Вы не против?"}, {"who": "Вы", "line": "…"}]'::jsonb,1,'17.1','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
