INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('17.3','situation','master_client','master_client','scn_17_3','Ребёнок мешает процедуре · Требование','Клиентка пришла с ребёнком 3–6 лет. Ребёнок бегает, трогает инструменты, кричит. На просьбу успокоить его клиентка реагирует агрессивно.','Я плачу деньги и имею право приводить своего ребёнка! Не лезьте не в своё дело!','[{"who": "Клиентка", "line": "Я плачу деньги и имею право приводить своего ребёнка! Не лезьте не в своё дело!"}, {"who": "Вы", "line": "…"}]'::jsonb,3,'17.3','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
