INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,task,example_dialogue,steps,criteria,card_no,batch_id) VALUES ('sol_18','solution','master_client','master_client','scn_18_1','Громкий телефонный разговор во время процедуры','Вежливо, но твёрдо попросить завершить разговор или говорить тише, чтобы не мешать процедуре и другим клиентам.','«Конечно, если нужно — я сделаю паузу, пока вы договорите. Но во время работы прошу говорить тише: рядом другие гости, а мне важна точность». Предложить паузу или продолжить без разговора.','[]'::jsonb,'[]'::jsonb,'18','beauty_v1') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cards(id,type,category_id,direction_id,scenario_id,title,description,opening_line,dialogue,level,card_no,linked_skill_id,batch_id) VALUES ('18.1','situation','master_client','master_client','scn_18_1','Громкий телефонный разговор во время процедуры · Вопрос','Клиентка постоянно громко разговаривает по телефону во время процедуры. Мастер не может сосредоточиться, другие клиенты чувствуют дискомфорт.','Я могу говорить по телефону во время процедуры? Мне нужно решить рабочий вопрос.','[{"who": "Клиентка", "line": "Я могу говорить по телефону во время процедуры? Мне нужно решить рабочий вопрос."}, {"who": "Вы", "line": "…"}]'::jsonb,1,'18.1','skill_rules_policy','beauty_v1') ON CONFLICT (id) DO NOTHING;
