DO $$
DECLARE r record; expr text;
BEGIN
  FOR r IN SELECT c.table_name, c.column_name, c.data_type FROM information_schema.columns c
    JOIN information_schema.tables t ON t.table_schema=c.table_schema AND t.table_name=c.table_name AND t.table_type='BASE TABLE'
    WHERE c.table_schema='public' AND c.data_type IN ('text','jsonb') AND c.table_name NOT IN ('cards','scenarios','categories','directions')
  LOOP
    expr := CASE WHEN r.data_type='jsonb' THEN format('%I::text', r.column_name) ELSE format('%I', r.column_name) END;
    expr := format($f$replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(%s,'клиникой','салоном'),'клиники','салона'),'клинике','салоне'),'клинику','салон'),'клиника','салон'),'Клиника','Салон'),'Клиники','Салона'),'пациентк','клиентк'),'Пациентк','Клиентк'),'пациент','клиент'),'Пациент','Клиент'),'врача','мастера'),'врачу','мастеру'),'врач','мастер'),'Врач','Мастер'),'Регистратура','Администратор')$f$, expr);
    IF r.data_type='jsonb' THEN expr := '(' || expr || ')::jsonb'; END IF;
    EXECUTE format('UPDATE public.%I SET %I = %s WHERE %I::text ~ %L', r.table_name, r.column_name, expr, r.column_name, '([Кк]линик|[Пп]ациент|[Вв]рач|Регистратур)');
  END LOOP;
END $$;
